{"op":"define","frontend":"flow","source":"word customer.discounted-balance(customer-record: Customer) -> Money {
    effects none
    doc "Apply a 10% discount to raw kind premium, truncating minor units toward zero."
    if customer::premium?(customer-record) {
        let amount = Money::value(customer::balance(customer-record))
        let tenths = ::divide(amount, 10)
        let remainder = ::subtract(amount, ::multiply(tenths, 10))
        let discounted-tenths = ::multiply(tenths, 9)
        let discounted-remainder = ::divide(::multiply(remainder, 9), 10)
        Money::new(::add(discounted-tenths, discounted-remainder))
    } else {
        customer::balance(customer-record)
    }
}

